import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.BXn5fPR3.js";const m=JSON.parse('{"title":"Artifacts: Audio files","description":"","frontmatter":{},"headers":[],"relativePath":"artifacts/audio.md","filePath":"artifacts/audio.md"}'),o={name:"artifacts/audio.md"};function r(n,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="artifacts-audio-files" tabindex="-1">Artifacts: Audio files <a class="header-anchor" href="#artifacts-audio-files" aria-label="Permalink to &quot;Artifacts: Audio files&quot;">​</a></h1><p>Sounds the speaker itself can play on demand: button chimes, setup prompts, and calibration tones. None of these are music files; they are short built-in sounds the firmware keeps on board so it can answer instantly without downloading anything.</p><details class="details custom-block"><summary>Technical details</summary><p>Playback is triggered through x-rincon-buzzer:, x-rincon-configmode: and x-rincon-sonarcal: URIs resolved against /opt/buzzers and (for downloaded tones) an ETag-managed cache.</p></details><h3 id="_0-mp3" tabindex="-1"><code>0.mp3</code> <a class="header-anchor" href="#_0-mp3" aria-label="Permalink to &quot;`0.mp3`&quot;">​</a></h3><p>The loudest of the four numbered button chimes. The player plays this through its own speaker when a physical button press needs a clear audible confirmation, such as the final step of a setup or pairing gesture.</p><div class="artifact-audio"><audio controls preload="none" src="/anacapad-internals/files/opt/buzzers/0.mp3"></audio></div><p><a href="/anacapad-internals/files/opt/buzzers/0.mp3">Download</a> · 85.9 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/0.mp3</code></li><li><strong>Category:</strong> audio</li><li><strong>Size:</strong> 85.9 KB (87989 bytes)</li><li><strong>SHA-256:</strong> <code>9448835023747a67c6a060bc168b32fa11c9bb4018727a27d10e9961da3dc250</code></li></ul><p>Buzzer asset index 0, about 88 KB. Resolved by the x-rincon-buzzer:0 URI family and played through the mixer on the alert path rather than the music pipeline.</p></details><h3 id="_1-mp3" tabindex="-1"><code>1.mp3</code> <a class="header-anchor" href="#_1-mp3" aria-label="Permalink to &quot;`1.mp3`&quot;">​</a></h3><p>A quieter numbered chime used for softer confirmations. It sits alongside the other numbered buzzers as part of the small vocabulary of sounds the player can make without involving a music service.</p><div class="artifact-audio"><audio controls preload="none" src="/anacapad-internals/files/opt/buzzers/1.mp3"></audio></div><p><a href="/anacapad-internals/files/opt/buzzers/1.mp3">Download</a> · 40.3 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/1.mp3</code></li><li><strong>Category:</strong> audio</li><li><strong>Size:</strong> 40.3 KB (41288 bytes)</li><li><strong>SHA-256:</strong> <code>e9ccea41f9c98e27b355fe68034dbf77274f3df004cfef18f9ead1817c33a28d</code></li></ul><p>Buzzer asset index 1, about 41 KB. Same alert-path playback as 0.mp3; the four numbered files form the graded confirmation set.</p></details><h3 id="_100-mp3" tabindex="-1"><code>100.mp3</code> <a class="header-anchor" href="#_100-mp3" aria-label="Permalink to &quot;`100.mp3`&quot;">​</a></h3><p>Another of the numbered confirmation sounds, used for a different stage or type of action than the low-numbered chimes.</p><div class="artifact-audio"><audio controls preload="none" src="/anacapad-internals/files/opt/buzzers/100.mp3"></audio></div><p><a href="/anacapad-internals/files/opt/buzzers/100.mp3">Download</a> · 41.1 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/100.mp3</code></li><li><strong>Category:</strong> audio</li><li><strong>Size:</strong> 41.1 KB (42061 bytes)</li><li><strong>SHA-256:</strong> <code>35669519666e9a07838c621dfaf809fe2086d53790d02ddcfa5ed19622e41733</code></li></ul><p>Buzzer asset index 100, about 42 KB. The jump in numbering suggests a second group of sounds for a distinct event class inside the same directory.</p></details><h3 id="_101-mp3" tabindex="-1"><code>101.mp3</code> <a class="header-anchor" href="#_101-mp3" aria-label="Permalink to &quot;`101.mp3`&quot;">​</a></h3><p>The smallest buzzer file, a very short tick or blip used for the lightest possible confirmation.</p><div class="artifact-audio"><audio controls preload="none" src="/anacapad-internals/files/opt/buzzers/101.mp3"></audio></div><p><a href="/anacapad-internals/files/opt/buzzers/101.mp3">Download</a> · 4.9 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/101.mp3</code></li><li><strong>Category:</strong> audio</li><li><strong>Size:</strong> 4.9 KB (5054 bytes)</li><li><strong>SHA-256:</strong> <code>6e68b9122065d617ec6c081365345d04091a48b646699e8f478798923c9f9a45</code></li></ul><p>Buzzer asset index 101, about 5 KB. Its size implies a sub-second clip, consistent with a minimal UI tick.</p></details><h3 id="speaker-detect-mp3" tabindex="-1"><code>speaker-detect.mp3</code> <a class="header-anchor" href="#speaker-detect-mp3" aria-label="Permalink to &quot;`speaker-detect.mp3`&quot;">​</a></h3><p>The loud chirp a speaker emits when the app asks &#39;which box is this?&#39; During setup or diagnostics the player plays this tone so you can identify which physical speaker you are configuring.</p><div class="artifact-audio"><audio controls preload="none" src="/anacapad-internals/files/opt/buzzers/speaker-detect.mp3"></audio></div><p><a href="/anacapad-internals/files/opt/buzzers/speaker-detect.mp3">Download</a> · 248.8 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/speaker-detect.mp3</code></li><li><strong>Category:</strong> audio</li><li><strong>Size:</strong> 248.8 KB (254725 bytes)</li><li><strong>SHA-256:</strong> <code>1611d71bab8d9a7a7d72ae6afc662c6637a9d4eaca9272166de6e54e9c1ff934</code></li></ul><p>About 255 KB, the largest buzzer by far because it is a longer identification tone. This is the file behind the &#39;chirp&#39; feature and the x-rincon-configmode:speaker-detect URI documented in the URI formats page.</p></details>',28)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
